import {suggestDecisions,pausableRates,saveSuggestion} from './decision-assistant.js';
import {uid,euro,compact,fieldMoney,money,monthName,shiftMonth} from './planner.js';
import {newVariant,saveDecision,evaluateScenario,scenarioPlan,adoptScenario,undoScenario} from './scenarios.js';

export function createScenarioUI(ctx){
 const {esc,btn}=ctx;let selected='',variant='',stress=false,assistantResults=null;
 const close=()=>document.querySelector('#dialog').close();
 const get=()=>{const d=ctx.state.decisions.find(d=>d.id===selected);if(!d)throw Error('Bitte die Entscheidung erneut öffnen.');return d;};
 const current=d=>d.variants.find(v=>v.id===variant)||d.variants[0];
 const editable=()=>{const d=get();if(d.applied)throw Error('Nimm diese Übernahme zuerst zurück.');return structuredClone(d);};
 const action=(label,name,id='',style='textbtn')=>`<button type="button" class="${style}" data-action="${name}" data-id="${id}">${label}</button>`;
 const footer=(label='Speichern')=>`<div class="form-footer">${action('Abbrechen','close','','btn btn-outline')}<button class="btn btn-primary" type="submit">${label}</button></div>`;
 const options=(entries,value)=>entries.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
 const amount=(name,label,value=0)=>`<label><span>${label} (€)</span><input name="${name}" inputmode="decimal" value="${fieldMoney(value)}" required></label>`;
 const write=d=>{if(ctx.persist(saveDecision(ctx.state,d),'Entscheidung gespeichert')){selected=d.id;close();ctx.render();}};
 function form(title,html,save){const revision=ctx.state.revision;ctx.openDialog(title,`<form>${html}</form>`,f=>{if(ctx.state.revision!==revision)throw Error('Dein Plan hat sich geändert. Bitte öffne das Formular erneut.');save(new FormData(f));});}
 function settings(isNew=false){const d=isNew?{id:uid(),title:'',start:ctx.month>'2100-01'?'2100-01':ctx.month,minFree:0,protected:[],variants:[]}:editable(),locked=d.variants.some(v=>v.lines.length);
 form(isNew?'Entscheidung anlegen':'Rahmen & Grenzen',`<label><span>Was möchtest Du durchspielen?</span><input name="title" maxlength="100" placeholder="z. B. Ein Auto kaufen" value="${esc(d.title)}" required></label><div class="form-grid spaced"><label><span>Startmonat</span><input type="month" name="start" min="2000-01" max="2100-01" value="${d.start}" ${locked?'readonly':''} required></label>${amount('minFree','Mindestens frei pro Monat',d.minFree)}</div><p class="helper">Verglichen werden zwölf Monate. ${locked?'Der Start bleibt fest, sobald Posten angelegt sind. ':''}Dein bestehender Plan wird automatisch als Vergleich verwendet.</p><h3 class="spaced">Geschützte Rücklagen</h3><p class="helper">Diese Beträge sollen am Monatsende mindestens im jeweiligen Topf bleiben.</p>${ctx.state.pots.map(p=>`<div class="scenario-protection"><label class="scenario-check"><input type="checkbox" name="protected" value="${p.id}" ${d.protected.some(x=>x.potId===p.id)?'checked':''}><span>${esc(p.name)}</span></label>${amount('min_'+p.id,'Mindestbestand',d.protected.find(x=>x.potId===p.id)?.minimum||0)}</div>`).join('')||'<p class="helper">Du hast noch keine Rücklagentöpfe angelegt.</p>'}${footer(isNew?'Entscheidung anlegen':'Grenzen speichern')}`,fd=>{d.title=String(fd.get('title')||'').trim();const nextStart=locked?d.start:String(fd.get('start')),serial=m=>Number(m.slice(0,4))*12+Number(m.slice(5)),delta=serial(nextStart)-serial(d.start);if(delta)for(const v of d.variants)v.stress.month=shiftMonth(v.stress.month,delta);d.start=nextStart;d.minFree=money(fd.get('minFree'));d.protected=fd.getAll('protected').map(potId=>({potId,minimum:money(fd.get('min_'+potId))}));if(isNew)d.variants=[newVariant('Variante 1',d.start)];write(d);});}
 function variantEditor(isNew=false){const d=editable(),v=isNew?newVariant('Neue Variante',d.start):current(d),seen=new Set(),items=ctx.state.items.filter(i=>{if(i.source||i.end&&i.end<d.start||i.frequency==='once'&&i.start<d.start)return false;const key=i.frequency==='once'?i.id:i.groupId||i.id;if(seen.has(key))return false;seen.add(key);return true;});
 form(isNew?'Weitere Variante':'Variante bearbeiten',`<label><span>Name</span><input name="name" maxlength="80" value="${esc(v.name)}" required></label><h3 class="spaced">Welche bestehenden Posten entfallen?</h3><p class="helper">Ab ${monthName(d.start)}. Bei laufenden Posten gilt das für die gesamte Serie samt späteren Änderungen. Frühere Monate bleiben erhalten.</p><div class="scenario-checklist">${items.map(i=>`<label class="scenario-check"><input type="checkbox" name="removed" value="${i.id}" ${v.removedIds.some(id=>{const x=ctx.state.items.find(x=>x.id===id);return id===i.id||i.frequency!=='once'&&x&&(x.groupId||x.id)===(i.groupId||i.id)})?'checked':''}><span>${esc(i.title)}<small>${euro(i.amount)} · ${{month:'monatlich',quarter:'alle 3 Monate',year:'jährlich',once:monthName(i.start)}[i.frequency]}</small></span></label>`).join('')||'<p class="helper">Keine passenden Planposten vorhanden.</p>'}</div>${footer()}`,fd=>{v.name=String(fd.get('name')||'').trim();v.removedIds=fd.getAll('removed');if(isNew)d.variants.push(v);variant=v.id;write(d);});}
 function lineEditor(id){const d=editable(),v=current(d),l=v.lines.find(l=>l.id===id)||{id:uid(),title:'',amount:0,type:'expense',frequency:'month',start:d.start,end:'',category:ctx.state.categories[0].id,potId:'',note:''};
 form(id?'Szenarioposten bearbeiten':'Szenarioposten hinzufügen',`<label><span>Posten</span><input name="title" maxlength="160" value="${esc(l.title)}" placeholder="z. B. Versicherung, Kaufpreis oder Gehaltsplus" required></label><div class="form-grid spaced">${amount('amount','Betrag',l.amount)}<label><span>Art</span><select name="type">${options([['expense','Ausgabe'],['income','Einnahme / Entnahme'],['saving','Sparrate']],l.type)}</select></label><label><span>Häufigkeit</span><select name="frequency">${options([['month','Monatlich'],['quarter','Alle 3 Monate'],['year','Jährlich im Zahlungsmonat'],['once','Einmalig']],l.frequency)}</select></label><label><span>Kategorie</span><select name="category">${options(ctx.state.categories.map(c=>[c.id,c.name]),l.category)}</select></label><label><span>Ab Monat</span><input type="month" name="start" min="${d.start}" max="2100-12" value="${l.start}" required></label><label><span>Bis Monat (optional)</span><input type="month" name="end" min="${l.start}" max="2100-12" value="${l.end}"></label></div><label class="spaced"><span>Rücklagentopf (optional)</span><select name="potId">${options([['','Ohne Topf · aus dem Monatsbudget'],...ctx.state.pots.map(p=>[p.id,p.name])],l.potId)}</select></label><p class="helper">Ausgabe + Topf: Kauf wird aus diesem Topf bezahlt. Sparrate + Topf: Einzahlung. Einnahme + Topf: Entnahme. Bei jährlichen Posten ist „Ab Monat“ der erste Zahlungsmonat. Danach zählt der volle Betrag alle zwölf Monate.</p>${footer('Im Szenario speichern')}`,fd=>{const line={...l,title:String(fd.get('title')||'').trim(),amount:money(fd.get('amount')),type:fd.get('type'),frequency:fd.get('frequency'),start:String(fd.get('start')),end:String(fd.get('end')||''),category:fd.get('category'),potId:fd.get('potId')||''};if(line.frequency==='once')line.end='';if(['quarter','year'].includes(line.frequency))line.cycleStart=line.start;else delete line.cycleStart;if(line.frequency==='year')line.annualPayment=true;else delete line.annualPayment;const index=v.lines.findIndex(x=>x.id===id);if(index<0)v.lines.push(line);else v.lines[index]=line;write(d);});}
 function stressEditor(){const d=editable(),v=current(d),s=v.stress;form('Belastungstest',`<p class="helper">Zusätzliche Belastungen nur für „${esc(v.name)}“. Du kannst jederzeit zwischen normalem Verlauf und Test wechseln.</p>${amount('monthly','Zusätzliche Ausgaben pro Monat',s.monthly)}<div class="form-grid spaced">${amount('once','Einmalige Sonderausgabe',s.once)}<label><span>Monat der Sonderausgabe</span><input type="month" name="month" min="${d.start}" max="${shiftMonth(d.start,11)}" value="${s.month}" required></label></div><label class="spaced"><span>Sonderausgabe bezahlen aus</span><select name="potId">${options([['','Monatsbudget'],...ctx.state.pots.map(p=>[p.id,p.name])],s.potId)}</select></label>${footer('Test speichern')}`,fd=>{v.stress={monthly:money(fd.get('monthly')),once:money(fd.get('once')),month:fd.get('month'),potId:fd.get('potId')||''};stress=true;write(d);});}
 function metrics(r){return `<dl class="scenario-metrics"><div><dt>Ø frei / Monat</dt><dd>${euro(r.average)}</dd></div><div><dt>Knappster Monat</dt><dd class="${r.minRemaining<0?'negative':''}">${euro(r.minRemaining)}</dd></div><div><dt>Zusätzliche Einmalkäufe zum Start</dt><dd>${euro(r.upfront)}</dd></div><div><dt>Rücklagen nach 12 Monaten</dt><dd>${euro(r.rows.at(-1).reserves.balance)}</dd></div></dl>`;}
 function chart(base,result,key,title,minimum=null){
 const values=rows=>rows.map(r=>key==='free'?r.remaining:r.reserves.balance),a=values(base.rows),b=values(result.rows),lo=Math.min(0,...a,...b,minimum??0),hi=Math.max(100,...a,...b,minimum??0),span=hi-lo||1,x=i=>60+i*42,y=v=>170-(v-lo)/span*140,path=vals=>vals.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ');
 return `<figure class="scenario-chart"><figcaption>${title}</figcaption><svg viewBox="0 0 550 205" role="img" aria-label="${title}. Genaue Werte in der Tabelle darunter.">${[lo,(hi+lo)/2,hi].map(v=>`<line x1="60" x2="522" y1="${y(v)}" y2="${y(v)}" stroke="#d7d5cb"/><text x="51" y="${y(v)+4}" text-anchor="end">${compact(v)}</text>`).join('')}${minimum!==null?`<line x1="60" x2="522" y1="${y(minimum)}" y2="${y(minimum)}" stroke="#b38a30" stroke-dasharray="2 5"/>`:''}<path d="${path(a)}" stroke="#807496" stroke-width="2" stroke-dasharray="6 5" fill="none"/><path d="${path(b)}" stroke="#315d54" stroke-width="3" fill="none"/>${b.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#315d54"><title>${monthName(result.rows[i].month)}: ${euro(v)}</title></circle>`).join('')}${[0,5,11].map(i=>`<text x="${x(i)}" y="195" text-anchor="${i===0?'start':i===11?'end':'middle'}">${monthName(result.rows[i].month)}</text>`).join('')}</svg><div class="scenario-chart-legend"><span><i class="baseline"></i>Bisheriger Plan</span><span><i></i>Variante${stress?' + Belastung':''}</span>${minimum!==null?'<span><i class="minimum"></i>Deine Grenze</span>':''}</div></figure>`;
 }
 function comparison(d,v,base,result){const rows=result.rows;return `<section class="scenario-detail"><div class="scenario-section-head"><div><span class="goal-kicker">Zwölf Monate im Vergleich</span><h2>${esc(v.name)}${stress?' · Belastungstest':''}</h2></div>${action('Test einstellen','scenario-stress')}</div><div class="scenario-verdict ${result.violations.length?'is-warning':''}"><strong>${result.violations.length?'Deine Grenzen werden unterschritten':'Deine eingestellten Grenzen bleiben eingehalten'}</strong><p>${result.violations.length?`In ${new Set(result.violations.map(x=>x.month)).size} von 12 Monaten. Die Einzelheiten findest Du unten.`:'Gilt für die eingetragenen Beträge und die nächsten zwölf Monate.'}</p></div>${chart(base,result,'free','Dein freier Monatsbetrag',d.minFree)}${chart(base,result,'reserves','Deine Rücklagen gesamt')}<details class="scenario-expand"><summary>Genaue Monatswerte</summary><div class="scenario-table-wrap"><table class="scenario-table"><caption>Freier Monatsbetrag und gesamter Rücklagenbestand am Monatsende</caption><thead><tr><th>Monat</th><th>Frei bisher</th><th>Frei Variante</th><th>Töpfe bisher</th><th>Töpfe Variante</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><th>${monthName(r.month)}</th><td>${euro(base.rows[i].remaining)}</td><td class="${r.remaining<d.minFree?'negative':''}">${euro(r.remaining)}</td><td>${euro(base.rows[i].reserves.balance)}</td><td>${euro(r.reserves.balance)}</td></tr>`).join('')}</tbody></table></div></details>${ctx.state.pots.length?`<details class="scenario-expand"><summary>Verlauf der einzelnen Töpfe</summary>${ctx.state.pots.map(p=>`<div class="scenario-table-wrap"><table class="scenario-table"><caption>${esc(p.name)} · Monatsendstände</caption><thead><tr><th>Monat</th><th>Bisher</th><th>Variante</th><th>Differenz</th></tr></thead><tbody>${rows.map((r,i)=>{const a=base.rows[i].reserves.pots.find(x=>x.id===p.id)?.balance||0,b=r.reserves.pots.find(x=>x.id===p.id)?.balance||0;return `<tr><th>${monthName(r.month)}</th><td>${euro(a)}</td><td>${euro(b)}</td><td>${euro(b-a)}</td></tr>`;}).join('')}</tbody></table></div>`).join('')}</details>`:''}${result.goals.length?`<h3 class="spaced">Was bedeutet das für Deine Wünsche?</h3><div class="scenario-goals">${result.goals.map((g,i)=>`<article><strong>${esc(g.goal.title)}</strong><p>${g.balance===null?'Ohne Topf lässt sich noch kein Zeitpunkt berechnen.':`Preis gedeckt: bisher ${base.goals[i].reach?monthName(base.goals[i].reach):'nicht im Zeitraum'} → ${g.reach?monthName(g.reach):'nicht im Zeitraum'}.<br>Ende ${monthName(g.at)} fehlen ${euro(g.missing)}.`}</p></article>`).join('')}</div>`:''}${result.violations.length?`<details class="scenario-expand"><summary>Grenzverletzungen ansehen (${result.violations.length})</summary><ul class="scenario-warnings">${result.violations.map(x=>`<li>${monthName(x.month)} · ${x.kind==='free'?'Frei verfügbar':esc(x.name)}: ${euro(x.value)} statt mindestens ${euro(x.minimum)}</li>`).join('')}</ul></details>`:''}<p class="helper spaced">Der Vergleich verwendet Deinen aktuellen Plan. Freies Geld wird nicht automatisch gespart. Bestehende Sparraten laufen auch bei einem Budgetdefizit rechnerisch weiter. Zieltermine zeigen die erste Deckung im Vergleichszeitraum, keinen tatsächlichen Kauf. Spätere Bestandskorrekturen in Töpfen bleiben wirksam.</p>${btn('Änderungen vor Übernahme prüfen','scenario-preview','primary','arrow')}</section>`;}
 function render(){const d=ctx.state.decisions.find(d=>d.id===selected);if(!d)return `<div class="goals-toolbar"><p>Große Entscheidungen. Erst durchspielen, dann festlegen.</p>${btn('Neue Entscheidung','scenario-new')}</div>${ctx.state.decisions.length?`<div class="goals-grid">${ctx.state.decisions.map(d=>`<article class="goal-card"><span class="goal-kicker">${d.applied?'Im Plan übernommen':'Separater Entwurf'}</span><h2>${esc(d.title)}</h2><p class="helper">Ab ${monthName(d.start)} · ${d.variants.length} Variante${d.variants.length===1?'':'n'}</p>${action('Öffnen','scenario-open',d.id,'btn btn-outline')}</article>`).join('')}</div>`:`<section class="goal-empty"><span class="goal-kicker">Was wäre, wenn …</span><h2>Passt die Entscheidung in Dein Leben?</h2><p>Vergleiche zum Beispiel zwei Autos, eine größere Reise oder eine berufliche Veränderung. Dein Monatsplan und Deine Rücklagen bilden die Grundlage.</p>${btn('Entscheidung durchspielen','scenario-new')}</section>`}`;
 if(d.applied)return `${action('← Alle Entscheidungen','scenario-back')}<section class="scenario-detail"><span class="goal-kicker">Im Monatsplan übernommen</span><h2>${esc(d.title)}</h2><p>${esc(d.variants.find(v=>v.id===d.applied.variantId)?.name)}${d.applied.stress?' inklusive Belastungstest':''} wurde übernommen.</p><p class="helper">Die Übernahme ist gespeichert. Du kannst sie auch nach einem Neustart zurücknehmen. Falls betroffene Posten inzwischen bearbeitet wurden, stoppt die Rücknahme zum Schutz Deiner Änderungen.</p>${action('Übernahme zurücknehmen','scenario-undo','','btn btn-outline')}</section>`;
 const v=current(d),base=evaluateScenario(ctx.state,d);let result,error='';try{result=evaluateScenario(ctx.state,d,v,stress);}catch(e){error=e.message;}
 return `${action('← Alle Entscheidungen','scenario-back')}<div class="scenario-title"><div><span class="goal-kicker">Separates Szenario · ab ${monthName(d.start)}</span><h2>${esc(d.title)}</h2><p class="helper">Mindestens ${euro(d.minFree)} frei / Monat · ${d.protected.length} geschützte Töpfe</p></div>${action('Rahmen & Grenzen','scenario-settings')}</div><div class="scenario-tabs" role="group" aria-label="Berechnung"><button data-action="scenario-normal" aria-pressed="${!stress}" class="${!stress?'active':''}">Normaler Verlauf</button><button data-action="scenario-test" aria-pressed="${stress}" class="${stress?'active':''}">Belastungstest</button></div><div class="scenario-comparisons"><article class="scenario-option is-baseline"><span class="goal-kicker">Referenz</span><h3>Dein bestehender Plan</h3>${metrics(base)}<p class="helper">${base.violations.length?'Auch der bisherige Plan unterschreitet eingestellte Grenzen.':'Unveränderter Monatsplan'}</p></article>${d.variants.map(x=>{let r;try{r=evaluateScenario(ctx.state,d,x,stress);}catch{}return `<article class="scenario-option ${x.id===v.id?'selected':''}">${action(esc(x.name),'scenario-select',x.id,'scenario-select')}<span class="goal-kicker">${x.id===v.id?'Ausgewählt':'Variante'}</span>${r?metrics(r):'<p class="negative">Zuordnungen bitte prüfen.</p>'}</article>`;}).join('')}</div><div class="scenario-section-head"><h3>Bausteine · ${esc(v.name)}</h3><div>${action('Variante bearbeiten','scenario-variant')}${d.variants.length<5?action('＋ Variante','scenario-variant-new'):''}</div></div><p class="helper">Ergänze nur die Änderungen zum bestehenden Plan. Einnahmen und Sparraten können ebenfalls angepasst werden.</p><div class="scenario-lines">${v.lines.map(l=>`<div class="scenario-line"><span class="scenario-rail ${l.type}"></span><div><strong>${esc(l.title)}</strong><small>${{expense:'Ausgabe',saving:'Sparrate',income:'Einnahme / Entnahme'}[l.type]} · ${{month:'monatlich',quarter:'alle 3 Monate',year:l.annualPayment?'jährlich im Zahlungsmonat':'bisheriger Monatsanteil',once:'einmalig'}[l.frequency]} · ab ${monthName(l.start)}${l.end?' bis '+monthName(l.end):''}${l.potId?' · '+esc(ctx.state.pots.find(p=>p.id===l.potId)?.name||'Topf fehlt'):''}</small></div><b>${euro(l.amount)}</b>${action('Bearbeiten','scenario-line',l.id)}${action('×','scenario-line-delete',l.id,'iconbtn')}</div>`).join('')||'<p class="scenario-empty-line">Noch keine zusätzlichen Posten. Lege zum Beispiel Kaufpreis und laufende Kosten an.</p>'}</div><p class="helper">${v.removedIds.length?v.removedIds.length+' bestehende Posten / Serien entfallen ab dem Startmonat.':'Alle bisherigen Planposten laufen weiter.'}</p><div class="inline spaced">${btn('Posten hinzufügen','scenario-line-new','outline')}${btn('Passende Alternativen finden','scenario-assistant','outline','spark')}${action('Belastung einstellen','scenario-stress')}${d.variants.length>1?action('Variante löschen','scenario-variant-delete'):''}</div>${stress?`<p class="scenario-stress-note">Zusätzlich: ${euro(v.stress.monthly)} / Monat und ${euro(v.stress.once)} im ${monthName(v.stress.month)}.${!v.stress.monthly&&!v.stress.once?' Noch keine Belastung eingestellt.':''}</p>`:''}${error?`<div class="notice error" role="alert">${esc(error)}</div>`:comparison(d,v,base,result)}${action('Entscheidung löschen','scenario-delete','','textbtn danger-zone spaced')}`;
 }
 function preview(){const d=get(),v=current(d),n=scenarioPlan(ctx.state,d,v,stress).state,r=evaluateScenario(ctx.state,d,v,stress),old=new Map(ctx.state.items.map(i=>[i.id,i])),changes=n.items.filter(i=>JSON.stringify(i)!==JSON.stringify(old.get(i.id))),deleted=ctx.state.items.filter(i=>!n.items.some(x=>x.id===i.id)),mode=stress;form('Änderungen prüfen',`<p><strong>${esc(d.title)} · ${esc(v.name)}</strong>${mode?' inklusive Belastungstest':''}</p><p class="helper">Diese Posten werden im echten Monatsplan gespeichert. Frühere Monate bleiben erhalten. Erfasste Monatsausgaben werden nicht verändert.</p><ul class="scenario-preview">${changes.map(i=>`<li><strong>${old.has(i.id)?'Beenden':'Neu'}: ${esc(i.title)}</strong><span>${euro(i.amount)} · ${{month:'monatlich',quarter:'alle 3 Monate',year:i.annualPayment?'jährlich im Zahlungsmonat':'bisheriger Monatsanteil',once:'einmalig'}[i.frequency]} · ${monthName(i.start)}${i.end?' bis '+monthName(i.end):''}${i.potId?' · '+esc(ctx.state.pots.find(p=>p.id===i.potId)?.name):''}</span></li>`).join('')}${deleted.map(i=>`<li><strong>Entfernen: ${esc(i.title)}</strong><span>Ab ${monthName(d.start)}</span></li>`).join('')}</ul>${r.violations.length?`<p class="negative">Achtung: Deine eingestellten Grenzen werden in ${new Set(r.violations.map(x=>x.month)).size} Monaten unterschritten.</p>`:''}<p class="helper">Die Übernahme lässt sich hier zurücknehmen, solange die betroffenen Posten unverändert bleiben.</p>${footer('Jetzt in den Monatsplan übernehmen')}`,()=>{if(ctx.persist(adoptScenario(ctx.state,d.id,v.id,mode),'Variante in den Monatsplan übernommen'))close();});}
 function assistant(){const d=editable(),v=current(d);form('Passende Alternativen berechnen',`<p class="helper">Geprüft werden Deine Mindestbeträge für zwölf Monate ab Beginn der jeweiligen Alternative. Nur die unten freigegebenen Kosten und Sparraten sind verhandelbar. Der Belastungstest wird hierfür nicht verwendet.</p><label class="spaced"><span>Preis / Anzahlung dieses Postens verändern</span><select name="priceId">${options([['','Keinen Preis verändern'],...v.lines.filter(l=>l.type==='expense'&&l.frequency==='once').map(l=>[l.id,l.title])],'')}</select></label><h3 class="spaced">Diese laufenden Kosten dürfen sinken</h3>${v.lines.filter(l=>l.type==='expense'&&l.frequency!=='once').map(l=>`<label class="scenario-check"><input type="checkbox" name="running" value="${l.id}"><span>${esc(l.title)} · ${euro(l.amount)}</span></label>`).join('')||'<p class="helper">Noch keine laufenden Kosten im Szenario.</p>'}<h3 class="spaced">Diese bestehenden Sparraten dürfen pausieren</h3>${pausableRates(ctx.state,d.start).map(i=>`<label class="scenario-check"><input type="checkbox" name="pause" value="${i.id}"><span>${esc(i.title)} · ${euro(i.amount)}</span></label>`).join('')||'<p class="helper">Keine unveränderten monatlichen Sparraten ohne Ausnahmen vorhanden.</p>'}<label class="spaced"><span>Dauer einer erlaubten Sparpause</span><select name="pauseMonths">${options([['3','3 Monate'],['6','6 Monate'],['12','12 Monate']],'6')}</select></label><p class="helper spaced">Zusätzlich wird ein späterer Beginn innerhalb von 24 Monaten geprüft. Preise und laufende Kosten sind mathematische Grenzen, keine Marktangebote. Eine kleinere Anzahlung allein berücksichtigt keine zusätzliche Finanzierung; trage deren vollständige Kosten zuerst im Szenario ein.</p>${footer('Alternativen berechnen')}`,fd=>{assistantResults={revision:ctx.state.revision,...suggestDecisions(ctx.state,d,v,{priceId:fd.get('priceId'),runningIds:fd.getAll('running'),pauseIds:fd.getAll('pause'),pauseMonths:Number(fd.get('pauseMonths'))})};showSuggestions();});}
 function showSuggestions(){const a=assistantResults;ctx.openDialog('Deine berechneten Alternativen',`${a.original.ok?'<p class="helper">Die Ausgangsvariante hält Deine Grenzen bereits ein.</p>':''}${!a.proposals.length?'<div class="scenario-verdict is-warning"><strong>Mit diesen Freigaben ist keine passende Alternative möglich.</strong><p>Prüfe auch, ob schon der bestehende Monatsplan Deine Grenzen unterschreitet. Du kannst weitere Annahmen selbst im Szenario verändern.</p></div>':''}${a.proposals.map((p,i)=>`<article class="assistant-option"><span class="goal-kicker">Ab ${monthName(p.decision.start)}</span><h3>${esc(p.title)}</h3><p>${esc(p.kind==='price'?'Maximaler Preis für „'+p.priceTitle+'“: '+euro(p.priceAmount):p.description)}</p>${metrics(p.result)}<details class="spaced"><summary>Vorgeschlagene Posten</summary><ul class="scenario-preview">${p.variant.lines.map(l=>`<li>${esc(l.title)} · ${euro(l.amount)}<span>Ab ${monthName(l.start)}</span></li>`).join('')}</ul></details>${action('Als separaten Entwurf speichern','scenario-suggestion',String(i),'btn btn-outline')}</article>`).join('')}<p class="helper spaced">Das Speichern legt eine neue Entscheidung an. Dein Monatsplan ändert sich erst nach deren eigener Übernahmevorschau.</p>`);}
 const actions={
 'scenario-assistant':assistant,'scenario-suggestion':el=>{if(!assistantResults||assistantResults.revision!==ctx.state.revision)throw Error('Bitte die Vorschläge mit dem aktuellen Stand neu berechnen.');const p=assistantResults.proposals[Number(el.dataset.id)],n=saveSuggestion(ctx.state,p);if(ctx.persist(n,'Alternative als Entwurf gespeichert')){selected=n.decisions.at(-1).id;variant='';stress=false;close();ctx.render();}},
 'scenario-new':()=>settings(true),'scenario-open':el=>{selected=el.dataset.id;variant='';stress=false;ctx.render();},'scenario-back':()=>{selected='';ctx.render();},'scenario-settings':()=>settings(),
 'scenario-select':el=>{variant=el.dataset.id;ctx.render();},'scenario-normal':()=>{stress=false;ctx.render();},'scenario-test':()=>{stress=true;ctx.render();},'scenario-variant':()=>variantEditor(),'scenario-variant-new':()=>variantEditor(true),
 'scenario-line-new':()=>lineEditor(),'scenario-line':el=>lineEditor(el.dataset.id),'scenario-stress':stressEditor,'scenario-preview':preview,
 'scenario-line-delete':el=>{const d=editable();current(d).lines=current(d).lines.filter(l=>l.id!==el.dataset.id);ctx.commitUndo(saveDecision(ctx.state,d),'Szenarioposten entfernt');},
 'scenario-variant-delete':()=>{const d=editable();if(d.variants.length<2)return;const v=current(d);ctx.confirmDialog('Variante löschen?',`„${esc(v.name)}“ und ihre Szenarioposten entfernen?`,()=>{d.variants=d.variants.filter(x=>x.id!==v.id);if(ctx.commitUndo(saveDecision(ctx.state,d),'Variante entfernt'))close();},'Variante löschen');},
 'scenario-delete':()=>{const d=editable();ctx.confirmDialog('Entscheidung löschen?',`„${esc(d.title)}“ mit allen Varianten löschen?`,()=>{const n=structuredClone(ctx.state);n.decisions=n.decisions.filter(x=>x.id!==d.id);if(ctx.commitUndo(n,'Entscheidung entfernt')){selected='';close();ctx.render();}},'Löschen');},
 'scenario-undo':()=>{const d=get(),revision=ctx.state.revision;ctx.confirmDialog('Übernahme zurücknehmen?','Alle unveränderten Posten dieser Übernahme werden zurückgesetzt. Unabhängige Änderungen bleiben erhalten. Das Szenario steht danach wieder zum Vergleichen bereit.',()=>{if(revision!==ctx.state.revision)throw Error('Der Plan hat sich geändert. Bitte erneut prüfen.');if(ctx.persist(undoScenario(ctx.state,d.id),'Übernahme zurückgenommen'))close();},'Übernahme zurücknehmen');}
 };
 return {render,actions};
}
